<?php

namespace Database\Seeders;

use App\Http\Controllers\LibraryController;
use App\Models\AssetCategory;
use App\Models\LibraryAsset;
use App\Support\SvgSanitizer;
use Illuminate\Database\Seeder;

/**
 * Seeds the asset categories and the ORIGINAL sample SVG library (database/library, generated by generate.py).
 * Idempotent: existing keys are never touched, because character versions pin assets by id + hash.
 */
class LibrarySeeder extends Seeder
{
    public function run(): void
    {
        $dir = database_path('library');
        $manifest = json_decode((string) file_get_contents($dir.'/manifest.json'), true);

        foreach ($manifest['categories'] as $c) {
            AssetCategory::updateOrCreate(['slug' => $c['slug']], $c);
        }

        $added = 0;
        foreach ($manifest['assets'] as $a) {
            if (LibraryAsset::where('key', $a['key'])->exists()) {
                continue;
            }
            $clean = SvgSanitizer::clean((string) file_get_contents($dir.'/'.$a['file']));
            LibraryController::persistAsset(null, AssetCategory::where('slug', $a['category'])->firstOrFail(), $a['name'], $a['tags'], 'system', 'approved',
                $clean['svg'], 'image/svg+xml', 'svg', $clean['width'], $clean['height'], $clean['tintable'], $a['key'], ['licence' => 'Original, dibuat untuk proyek ini']);
            $added++;
        }
        $this->command?->info("Library: $added aset ditambahkan.");
    }
}
